      "content": "import { createClient } from 'npm:@supabase/supabase-js@2';

const jsonHeaders = { 'content-type': 'application/json' };

Deno.serve(async (req) => {
  // verify_jwt is enabled at the platform level, but authenticate explicitly
  // here as well so the identity used for authorization is never caller input.
  const authorization = req.headers.get('Authorization');
  const token = authorization?.replace(/^Bearer\s+/i, '');

  if (!token) {
    return new Response(JSON.stringify({ error: 'Unauthorized' }), {
      status: 401,
      headers: jsonHeaders,
    });
  }

  const supabase = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,
  );

  const { data: { user }, error: userError } = await supabase.auth.getUser(token);

  if (userError || !user) {
    return new Response(JSON.stringify({ error: 'Unauthorized' }), {
      status: 401,
      headers: jsonHeaders,
    });
